const ASK_TALL = ['BBB', '..B', '.BB', '...', '.B.']
const ASK_SHORT = ['BBB', '..B', '.B.']
const ZED = ['OOO', '.O.', 'OOO']
/** The landing specks: sideways speed and upward speed, in pixels per beat. */
const SPECKS: { vx: number; vy: number }[] = [
  { vx: 0.35, vy: 2.2 },
  { vx: 0.7, vy: 2.8 },
  { vx: 1.05, vy: 1.6 },
]
const SPECK_INK = ['R', 'Y', 'B'] as const
const GRAVITY = 0.9

const NEIGHBOURS: [number, number][] = [[1, 0], [-1, 0], [0, 1], [0, -1]]

/** A scattered, repeatable texture: about one pixel in `every`, with no lines or stripes. */
const speckle = (x: number, y: number, every: number) => (((x * 73856093) ^ (y * 19349663)) >>> 0) % every === 0

/** Depth of the lid and side, and the front face's edge, for a canvas of `size` pixels. */
function dims(size: number): { d: number; f: number } {
  const d = Math.max(3, Math.round(size * 0.16))
  return { d, f: Math.round(size * 0.75) - d }
}

/** The cube alone: a front fw×fh, a lid and a right side d deep, the badge, the face and an outline. */
function cube(fw: number, fh: number, d: number, p: Pose): Grid {
  const w = fw + d
  const h = fh + d
  const g: Grid = Array.from({ length: h }, () => Array<Key>(w).fill('.'))
  const set = (x: number, y: number, k: Key) => {
    const row = g[y]
    if (row && x >= 0 && x < w) row[x] = k
  }
  const front = (x: number, y: number, k: Key) => set(x, d + y, k)
  const side = (k: number, y: number, key: Key) => set(fw - 1 + k, d - k + y, key)

  for (let y = 0; y < fh; y++) for (let x = 0; x < fw; x++) front(x, y, speckle(x, y, 11) ? 'G' : 'W')
  for (let k = 1; k <= d; k++) for (let x = 0; x < fw; x++) set(k + x, d - k, speckle(x, k, 7) ? 'G' : 'T')
  for (let k = 1; k <= d; k++) for (let y = 0; y < fh; y++) side(k, y, 'S')
  for (let x = 0; x < fw; x++) front(x, 0, 'D')
  for (let y = 0; y < fh; y++) front(fw - 1, y, 'D')

  // The logo badge on the side: red square, yellow square, blue dot (round once it is 3 pixels wide).
  const m = d - 1
  ;(['R', 'Y', 'B'] as const).forEach((key, i) => {
    const top = 2 + i * (m + 1)
    for (let a = 0; a < m; a++) {
      for (let b = 0; b < m; b++) {
        const isCorner = (a === 0 || a === m - 1) && (b === 0 || b === m - 1)
        if (key === 'B' && m >= 3 && isCorner) continue
        if (top + b < fh - 1) side(1 + a, top + b, key)
      }
    }
  })

  // The face. Eye gap and mouth width follow the front's parity so both stay centred.
  // Eyes 2 pixels tall at terminal sizes; 3 only on a big face, where 2 would look small.
  const eh = fh >= 15 ? 3 : 2
  // Narrow the gap (by 2, keeping it centred) until both eyes clear the outline and the crease.
  let gap = fw % 2 ? 3 : 4
  while (fw - 4 - gap < 2 && gap > 1) gap -= 2
  const left = (fw - (4 + gap)) / 2
  // A glance moves both eyes, but never onto the outline (x 0) or the crease (x fw-1).
  const look = Math.max(1 - left, Math.min(fw - 5 - left - gap, p.look))
  const ey = 1 + Math.round((fh - 2) * 0.2) - (p.up ? 1 : 0)
  for (const ex of [left + look, left + 2 + gap + look]) {
    if (p.eyes === 'closed') {
      front(ex, ey + eh - 1, 'E')
      front(ex + 1, ey + eh - 1, 'E')
    } else {
      for (let r = 0; r < eh; r++) {
        front(ex, ey + r, 'E')
        front(ex + 1, ey + r, 'E')
      }
      if (p.eyes === 'open') front(ex, ey, 'H')
    }
  }
  // Rosy cheeks just under the outer corner of each eye.
  front(left, ey + eh, 'K')
  front(left + 3 + gap, ey + eh, 'K')
  // A wide U smile: corners up, a flat bottom between them.
  const mw = fw >= 9 ? (fw % 2 ? 5 : 4) : fw % 2 ? 3 : 4
  const mx = (fw - mw) / 2
  // The mouth sits midway between the cheeks and the bottom edge, not tucked under the eyes.
  const my = Math.max(ey + eh + 1, Math.floor((ey + eh + fh - 2) / 2))
  const mouth = my + 1 >= fh - 1 ? 'flat' : p.mouth
  for (let x = mx; x < mx + mw; x++) {
    const isInner = x > mx && x < mx + mw - 1
    if (mouth === 'smile') front(x, isInner ? my + 1 : my, 'E')
    if (mouth === 'open') {
      front(x, my, 'E')
      if (isInner) front(x, my + 1, 'R')
    }
    if (mouth === 'oh' && isInner) {
      front(x, my, 'E')
      front(x, my + 1, 'E')
    }
    if (mouth === 'flat' && isInner) front(x, my, 'E')
  }

  // The outline: every pixel touching the outside, red while flashing.
  const edge: Key = p.flash ? 'R' : 'O'
  const out = g.map(row => row.slice())
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      if (g[y]?.[x] === '.') continue
      if (NEIGHBOURS.some(([dx, dy]) => (g[y + dy]?.[x + dx] ?? '.') === '.')) out[y]![x] = edge
    }
  }
  return out
}

/** One frame on a size×size canvas: the cube standing on a shadow, lifted, squashed or shaken by the pose. */
function draw(size: number, p: Pose): Grid {
  const { d, f } = dims(size)
  const fw = f + p.squash
  const fh = f - p.squash
  const c = cube(fw, fh, d, p)
  const bw = fw + d
  const bh = fh + d
  const ground = size - 1
  const room = size - 1 - (f + d)
  const lift = Math.max(0, Math.min(Math.round(p.lift * room), size - 1 - bh))
  const x0 = Math.floor((size - bw) / 2) + p.dx
  const y0 = ground - bh - lift
  const g: Grid = Array.from({ length: size }, () => Array<Key>(size).fill('.'))
  const put = (x: number, y: number, k: Key) => {
    const row = g[y]
    if (row && x >= 0 && x < size && row[x] === '.') row[x] = k
  }
  c.forEach((row, y) => row.forEach((k, x) => k !== '.' && put(x0 + x, y0 + y, k)))
  const sw = Math.max(3, bw - 2 - lift * 2)
  const sx = Math.floor((size - sw) / 2)
  for (let i = 0; i < sw; i++) put(sx + i, ground, 'X')
  const stamp = (glyph: string[], gx: number, gy: number) =>
    glyph.forEach((row, y) => [...row].forEach((k, x) => k !== '.' && put(gx + x, gy + y, k as Key)))
  if (p.ask) {
    const glyph = y0 >= ASK_TALL.length ? ASK_TALL : ASK_SHORT
    stamp(glyph, x0 + Math.floor(fw / 2) - 1, Math.max(0, y0 - glyph.length))
  }
  if (p.z !== undefined) stamp(ZED, Math.min(size - 3, x0 + fw + p.z), Math.max(0, y0 - 3 - p.z))
  if (p.dots) {
    const cx = x0 + Math.floor(fw / 2)
    for (let i = 0; i < Math.min(3, p.dots); i++) put(cx - 2 + i * 2, Math.max(0, y0 - 2), SPECK_INK[i]!)
  }
  if (p.dust !== undefined) {
    // Specks fly from the standing cube's bottom corners on a falling arc, land, fade to grey and vanish;
    // a puff of dust slides out along the ground for the first beats. Anchored to the standing cube so
    // the specks don't jump as the body squashes and stretches.
    const t = p.dust
    const standW = f + d
    const standX = Math.floor((size - standW) / 2)
    for (const dir of [-1, 1]) {
      const base = dir < 0 ? standX - 1 : standX + standW
      const reach = Math.max(0, dir < 0 ? base : size - 1 - base)
      SPECKS.forEach((s, i) => {
        const ink: Key | undefined = t <= 3 ? SPECK_INK[dir < 0 ? i : 2 - i] : t <= 5 || (t === 6 && i !== 1) ? 'G' : undefined
        if (!ink) return
        const x = base + dir * Math.min(reach, Math.round(s.vx * t))
        const y = Math.min(ground - 1, Math.round(ground - 1 - (s.vy * t - 0.5 * GRAVITY * t * t)))
        put(x, y, ink)
      })
      if (t <= 3) put(base + dir * Math.min(reach, t), ground, 'G')
    }
  }
  return g
}

const cache = new Map<string, Frame[]>()

/** Every frame of a mood at a size; an unknown mood is idle, a size below MIN_SIZE is MIN_SIZE. */
export function frames(mood: Mood, size: number = WEB_SIZE): Frame[] {
  const m: Mood = MOODS.includes(mood) ? mood : 'idle'
  const s = Math.max(MIN_SIZE, Math.round(Number.isFinite(size) ? size : WEB_SIZE))
  const key = `${m}:${s}`
  const hit = cache.get(key)
  if (hit) return hit
  const list = SCRIPT[m].map(p => ({ grid: draw(s, p), ms: p.ms }))
  cache.set(key, list)
  return list
}

/** The frame showing `ms` into a mood's loop; each frame lasts at least `minFrameMs`. Any number is a valid time. */
export function frameAt(mood: Mood, ms: number, size: number = WEB_SIZE, minFrameMs = 0): Grid {
  const list = frames(mood, size)
  const lengths = list.map(f => Math.max(f.ms, minFrameMs))
  const total = lengths.reduce((a, b) => a + b, 0)
  let t = ((Math.floor(Number.isFinite(ms) ? ms : 0) % total) + total) % total
  for (let i = 0; i < list.length; i++) {
    const length = lengths[i] ?? 0
    if (t < length) return list[i]!.grid
    t -= length
  }
  return list[0]!.grid
}

const DEFAULT_COLOR = 0x01000000
const UPPER_HALF = 0x2580
const LOWER_HALF = 0x2584
const BASE64 = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'

function hexToRgb(hex: string): number {
  const n = Number.parseInt(hex.replace('#', ''), 16)
  return Number.isNaN(n) ? DEFAULT_COLOR : n
}

function toBase64(bytes: Uint8Array): string {
  let out = ''
  for (let i = 0; i < bytes.length; i += 3) {
    const a = bytes[i] ?? 0
    const b = bytes[i + 1]
    const c = bytes[i + 2]
    const n = (a << 16) | ((b ?? 0) << 8) | (c ?? 0)
    out += BASE64[(n >> 18) & 63]! + BASE64[(n >> 12) & 63]! + (b === undefined ? '=' : BASE64[(n >> 6) & 63]!) + (c === undefined ? '=' : BASE64[n & 63]!)
  }
  return out
}

/** How many terminal cells a grid takes: its width, and half its height. */
export function cellSize(grid: Grid): { columns: number; rows: number } {
  return { columns: grid[0]?.length ?? 0, rows: Math.ceil(grid.length / 2) }
}

/** A grid as a terminal Raster's `cells`: each cell a ▀ or ▄ carrying two stacked pixels. */
export function toCells(grid: Grid, palette: Palette): string {
  const { columns, rows } = cellSize(grid)
  const color = (k: Key | undefined) => (k === undefined || k === '.' ? undefined : hexToRgb(palette[k]))
  const view = new DataView(new ArrayBuffer(columns * rows * 12))
  for (let row = 0; row < rows; row++) {
    for (let col = 0; col < columns; col++) {
      const top = color(grid[row * 2]?.[col])
      const bottom = color(grid[row * 2 + 1]?.[col])
      const [glyph, fg, bg] =
        top === undefined && bottom === undefined
          ? [0x20, DEFAULT_COLOR, DEFAULT_COLOR]
          : top === undefined
            ? [LOWER_HALF, bottom ?? DEFAULT_COLOR, DEFAULT_COLOR]
            : [UPPER_HALF, top, bottom ?? DEFAULT_COLOR]
      const at = (row * columns + col) * 12
      view.setUint32(at, glyph, true)
      view.setUint32(at + 4, fg, true)
      view.setUint32(at + 8, bg, true)
    }
  }
  return toBase64(new Uint8Array(view.buffer))
}
